import React, { useState } from 'react';
import { ToggleButton } from 'primereact/togglebutton';

export default function Basic() {
    const [checked, setChecked] = useState(false);
    
    return (
        <ToggleButton 
            checked={checked}
            onChange={(e) => setChecked(e.value)}
            className="w100"
        />
    );
}